This solution uses the built-in `Intl.NumberFormat` object, which is the **recommended and most accurate way** to handle currency formatting in modern JavaScript, as it correctly handles locale-specific rules, currency symbols, and decimal separators.

```javascript
/**
 * Formats a number into a currency string based on a specified locale and currency code.
 *
 * @param {number} amount The number to format.
 * @param {string} currencyCode The ISO 4217 currency code (e.g., 'USD', 'EUR', 'JPY').
 * @param {string} locale The locale to use for formatting (e.g., 'en-US', 'de-DE').
 * @param {number} [minimumFractionDigits=2] The minimum number of decimal places to show.
 * @returns {string} The formatted currency string.
 */
function formatCurrency(amount, currencyCode, locale, minimumFractionDigits = 2) {
    if (typeof amount !== 'number' || isNaN(amount)) {
        return 'Invalid Amount';
    }
    if (typeof currencyCode !== 'string' || currencyCode.length === 0) {
        console.warn("Currency code is missing. Formatting without currency symbol.");
        currencyCode = 'USD'; // Default to USD if missing
    }
    if (typeof locale !== 'string' || locale.length === 0) {
        console.warn("Locale is missing. Using default locale.");
        locale = 'en-US'; // Default to en-US if missing
    }

    try {
        const formatter = new Intl.NumberFormat(locale, {
            style: 'currency',
            currency: currencyCode,
            minimumFractionDigits: minimumFractionDigits,
            maximumFractionDigits: minimumFractionDigits,
        });

        return formatter.format(amount);
    } catch (error) {
        console.error(`Error formatting currency for ${amount} (${currencyCode} in ${locale}):`, error);
        // Fallback: return a simple string representation if Intl fails
        return `${currencyCode} ${amount.toFixed(2)}`;
    }
}

