Here is a JavaScript function to chunk an array into groups of size `n`.

This solution provides a clean and efficient implementation using a `for` loop and array slicing.

```javascript
/**
 * Chunks an array into smaller arrays (chunks) of a specified size.
 *
 * @param {Array<any>} array The array to be chunked.
 * @param {number} size The desired size of each chunk. Must be a positive integer.
 * @returns {Array<Array<any>>} An array of arrays, where each inner array is a chunk.
 * @throws {Error} If the size is not a positive integer.
 */
function chunkArray(array, size) {
    if (typeof size !== 'number' || size <= 0 || !Number.isInteger(size)) {
        throw new Error("Chunk size must be a positive integer.");
    }

    if (!Array.isArray(array)) {
        throw new Error("Input must be an array.");
    }

    const result = [];
    let index = 0;

    while (index < array.length) {
        // Slice the array from the current index up to index + size
        const chunk = array.slice(index, index + size);
        result.push(chunk);
        // Move the index forward by the chunk size
        index += size;
    }

    return result;
}

// --- Examples ---

