console.log(`${temp2}°C is equal to ${fahrenheit2}°F`); // Output: 25°C is equal to 77°F

// Example 3: Converting 100°C (boiling point)
const temp3 = 100;
const fahrenheit3 = celsiusToFahrenheit(temp3);
console.log(`${temp3}°C is equal to ${fahrenheit3}°F`); // Output: 100°C is equal to 212°F
```

### Explanation:

