Here is a JavaScript function that groups an array of objects by a specified property.

This solution uses the `reduce` method, which is a very common and efficient way to transform an array into a single resulting object (in this case, an object where keys are the property values and values are arrays of the objects).

```javascript
/**
 * Groups an array of objects by the value of a specified property.
 *
 * @param {Array<Object>} arr The array of objects to group.
 * @param {string} key The property name by which to group the objects.
 * @returns {Object<string, Array<Object>>} An object where keys are the unique
 *          values of the grouping property, and values are arrays of objects
 *          that share that property value.
 */
function groupBy(arr, key) {
  if (!Array.isArray(arr)) {
    throw new Error("The first argument must be an array.");
  }
  if (typeof key !== 'string' || key.length === 0) {
    throw new Error("The second argument (key) must be a non-empty string.");
  }

  return arr.reduce((accumulator, currentObject) => {
    // Get the value of the grouping key for the current object
    const groupKey = currentObject[key];

    // If the accumulator doesn't have this group key yet, initialize it with an empty array
    if (!accumulator[groupKey]) {
      accumulator[groupKey] = [];
    }

    // Push the current object into the appropriate group
    accumulator[groupKey].push(currentObject);

    return accumulator;
  }, {}); // Initialize the accumulator as an empty object
}

// --- Example Usage ---

