     */
    constructor(initialValue = 0) {
        /**
         * @private
         * @type {number} The current value of the counter.
         */
        this._count = initialValue;
    }

    /**
     * Increments the counter by 1.
     * @returns {number} The new value of the counter.
     */
    increment() {
