Here is a C function that copies a string without using `strcpy`. I will provide a few common and robust methods.

### Method 1: Using `strncpy` (The Standard Library Approach)

While the prompt asks to avoid `strcpy`, `strncpy` is often the intended alternative when dealing with fixed-size buffer copying, although it has quirks (it might not null-terminate if the source is longer than the destination).

```c
#include <stdio.h>
#include <string.h>

/**
 * Copies a source string to a destination buffer using strncpy.
 * 
 * @param dest The destination buffer.
 * @param src The source string to copy.
 * @param dest_size The maximum size of the destination buffer.
 * @return A pointer to the destination buffer.
 */
char* strncpy_copy(char *dest, const char *src, size_t dest_size) {
    if (dest == NULL || src == NULL) {
        return NULL;
    }

    // Copy at most (dest_size - 1) characters to leave room for the null terminator
    strncpy(dest, src, dest_size - 1);

    // Manually ensure null termination, which strncpy doesn't guarantee if src is too long
    dest[dest_size - 1] = '\0';

    return dest;
}

int main() {
    char source[] = "Hello, World!";
    char destination[20];

    printf("Original source: %s\n", source);

    // Copy the string
    strncpy_copy(destination, source, sizeof(destination));

    printf("Copied destination: %s\n", destination);

    return 0;
}
```

### Method 2: Manual Iteration (The Fundamental Approach)

This method demonstrates the core logic of string copying by iterating through the source string and copying each character one by one, ensuring the null terminator is placed correctly at the end.

```c
#include <stdio.h>
#include <stddef.h> // For size_t

/**
 * Copies a source string to a destination buffer by manual iteration.
 * 
 * @param dest The destination buffer.
 * @param src The source string to copy.
 * @param dest_size The maximum size of the destination buffer (including space for '\0').
 * @return A pointer to the destination buffer.
 */
char* manual_copy(char *dest, const char *src, size_t dest_size) {
    if (dest == NULL || src == NULL) {
        return NULL;
    }

    size_t i = 0;
    // Iterate through the source string until the null terminator is found
    while (src[i] != '\0' && i < dest_size - 1) {
        dest[i] = src[i];
        i++;
    }

    // Manually place the null terminator at the end of the copied string
    dest[i] = '\0';

    return dest;
}

int main() {
    char source[] = "Manual Copy Example";
    char destination[50];

    printf("Original source: %s\n", source);

    // Copy the string
    manual_copy(destination, source, sizeof(destination));

    printf("Copied destination: %s\n", destination);

    return 0;
}
