    let test_strings = vec![
        "racecar",
        "hello",
        "A man, a plan, a canal: Panama",
        "Madam",
        "121",
        "rust",
    ];

    for s in test_strings {
        let result = is_palindrome(s);
        println!("'{}' is a palindrome: {}", s, result);
    }
}
