This example uses an `i64` return type to handle factorials up to $20!$ (since $20!$ is the largest factorial that fits within a standard 64-bit signed integer). For larger numbers, you would need a big integer library like `num-bigint`.

```rust
/// Computes the factorial of a non-negative integer n (n!).
///
/// # Arguments
///
/// * `n` - The non-negative integer for which to compute the factorial.
///
/// # Returns
///
/// The factorial of n as an i64. Returns 1 for n=0.
/// Returns 0 if n is negative (as factorials are typically undefined for negative numbers).
pub fn factorial(n: i32) -> i64 {
    if n < 0 {
        // Factorial is not defined for negative numbers.
        eprintln!("Error: Factorial is not defined for negative numbers.");
        return 0;
    }

    // We use u64 for the accumulator to prevent overflow for as long as possible,
    // although the final return type is i64.
    let mut result: u64 = 1;

    // Iterate from 1 up to n (inclusive)
    for i in 1..=n {
        // Cast i to u64 for multiplication
        let current_i = i as u64;

        // Check for potential overflow before multiplying.
        // Since the return type is i64 (max value ~9e18), we check if the next
        // multiplication will exceed u64::MAX.
        if let Some(new_result) = result.checked_mul(current_i) {
            result = new_result;
        } else {
            // Overflow occurred. For this simple implementation, we panic or return
            // a sentinel value. Panicking is often clearer for mathematical functions
            // where the input is expected to be small enough.
            eprintln!("Warning: Factorial of {} resulted in an overflow for i64.", n);
            // Return the maximum possible i64 value or handle the error as needed.
            return i64::MAX; 
        }
    }

    // Cast the final result back to i64. This is safe if the result fits in i64.
    result as i64
}

